#include <stdio.h>

int main(void) {
    unsigned value;
    if(scanf("%u", &value)!=1 || value>255) return 1;
    volatile unsigned status = value;
    unsigned snapshot = status;
    printf("%u\n", snapshot & 1u);
    return 0;
}
